fit_data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\Sym4D_cutsAndFits';
if ~exist('fit_resEi200','var')
    %fit_data_file = 'FitEn_cut200_1Dsbg_dirGH_dE20_fix_bg_slope.mat'; % fit 1D background with no Q-slope
    %fit_data_file = 'FitEn_cut200_1D_fit_bg_dirGH_dE20_fix_bg_slope.mat';%Externaly 2-exponent fit fixed bg at high momentum.
    fit_data_file = 'FitEn_cut200ref110_2D_dirGH_dE20_fix_bg_slope.mat';%Externaly 2-exponent fit fixed bg at high momentum.
    ld = load(fullfile(fit_data_path,fit_data_file));
    if isfield(ld,'fit_resEi200')
        fit_resEi200 = ld.fit_resEi200;
    else
        fit_resEi200 = ld.fit_res;
    end
end
data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits';
fit_file = 'multicuts_fit_dataGH_ei200meV.mat';
if ~exist('cuts2fit200','var')
    ld = load(fullfile(data_path,fit_file));
    cuts2fit200 = ld.cuts2fit200;
end
cuts2fit = cuts2fit200;
fit_res = fit_resEi200;
mi = maps_instrument(200,600,'S');
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
cl = cuts2fit200.cuts_list;
for i=1:numel(cl)
    cl{i} = cl{i}.set_instrument(mi);
    cl{i} = cl{i}.set_sample(sample);

    %cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_instrument(mi);
    %cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_sample(sample);
end

%%
acolor g
Sgnl = fit_res.S;  
pd(Sgnl);ly 0 2;liny;keep_figure %[output:1d66f0ee]
J0 = fit_res.J0;
pd(J0);ly 20 60;keep_figure %[output:6242c2d8]
% incorrect units fixture
G = fit_res.gamma;
G.s_axis.units = 'meV';
fit_res.gamma = G;
pd(G);ly 0 100;keep_figure %[output:2d9f6dcb]

dE = min(Sgnl.x(2:end)-Sgnl.x(1:end-1)) %[output:57dca3df]
e_min = Sgnl.x(1);

%%
En = 120 %[output:94ed2203]
dE_step = 2; %original energy transfer step data were binned to. No point in going finer
half_dE = 10;
en_range = [En-half_dE,dE_step,En+half_dE];
en_idx =  floor((En-e_min)/dE)+1;
the2Dcuts = cl%(1:2); %[output:00f8eab8]

%lfit_par= fit_res.all_fit_par(en_idx);
%lfit_par= fit_res.all_fit_par(end);
lds = load('fit_par3DatasetsdE(120-140)_Ei200.mat');
lfit_par = lds.fit_par3DsdE140Ei200;
lfit_par = rmfield(lfit_par,'valid_chunks');
lfit_par.bp = {lfit_par.bp,lfit_par.bp,lfit_par.bp};

lfit_par.p(4) = lfit_par.p(4)*(0.13/0.076);
%init_bg_params =
%cellfun(@(par)[par(1),par(3)],init_bg_params,'UniformOutput',false); % bg
%in case of 2-D fitting
%[fit_obj,fit_par,figa,figb]=fit_single_set(the2Dcuts,En,half_dE,dE_step,init_fg_params,init_bg_params,false)
%[fit_obj,fit_par,figa,figb]=fit_single_set(the2Dcuts,En,half_dE,dE_step,init_fg_params,init_bg_params(3),false)
[fit_obj,fit_par,figa,figb]=refit_singleset_peaks(the2Dcuts,en_range,lfit_par,0.2,true,false); %[output:5850e123] %[output:3ec7b506] %[output:3d5b0f52] %[output:33fe7229] %[output:27c1465d] %[output:50a63382] %[output:79348dba] %[output:754baf49] %[output:1407ff6e] %[output:71125fec] %[output:71988c2d] %[output:746174f9]


